(() => {
 'use strict';
 const local=['localhost','127.0.0.1'].includes(location.hostname);
 const active=j=>j&&['queued','generating','reviewing','validating'].includes(j.status);
 const styleLabel=value=>value==='photoreal'?'摄影写实':'清晰插画';
 const jobStyle=j=>j.visualStyle||(j.visualPolicy==='photoreal-v2'?'photoreal':'illustration');
 const day=value=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value));
 const stamp=value=>new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
 const labels={generating:'生成中',review:'待检查',publish:'待发布',published:'已发布 · 手动标记',failed:'生成失败',parked:'已暂存'};
 const stage=j=>active(j)?'generating':j.status==='parked'?'parked':!j.ready?'failed':j.publication?'published':j.reviewedAt?'publish':'review';
 let savedStyle='photoreal';try{const value=localStorage.getItem('orbit.atlas.visualStyle');if(['photoreal','illustration'].includes(value))savedStyle=value}catch{}
 let savedReview=true;try{savedReview=localStorage.getItem('orbit.atlas.reviewEnabled')!=='false'}catch{}
 const a={reviewEnabled:savedReview,limits:{maxTitleChars:20,maxBodyChars:1000},loaded:false,loading:false,busy:false,version:0,token:'',caps:null,jobs:[],queue:[],config:null,error:'',tab:'today',selected:null,origin:'today',scroll:{},mode:'production',visualStyle:savedStyle,testTopic:null,productionTopic:null,advanced:false,recentFilter:'recent',query:'',kind:'production',filter:'all',date:'',limit:12,topicQuery:'',topicFilter:'TODO',publishResult:null,timer:null};
 const current=()=>a.jobs.find(j=>j.id===a.selected);
 const running=()=>a.jobs.find(active);
 const pending=()=>a.queue.filter(q=>q.status==='TODO');
 function adopt(q){a.config=q;a.queue=q.items;if(a.productionTopic&&!(q.available||q.items.filter(x=>x.status==='TODO')).some(x=>x.topic===a.productionTopic.topic&&x.category===a.productionTopic.category))a.productionTopic=null;if(a.testTopic&&!q.items.some(x=>x.status==='TODO'&&x.topic===a.testTopic))a.testTopic=null}
 function put(job){const i=a.jobs.findIndex(j=>j.id===job.id);if(i<0)a.jobs.unshift(job);else a.jobs[i]=job}
 function route(){const p=new URLSearchParams(location.hash.split('?')[1]||'');a.selected=p.get('job');a.tab=['today','library','topics'].includes(p.get('view'))?p.get('view'):'today';a.origin=['today','library','topics'].includes(p.get('from'))?p.get('from'):a.selected?'library':a.tab;a.publishResult=null}
 route();
 names.atlas='拾光百科';
 const nav=document.createElement('button');nav.className='nav-item';nav.dataset.nav='atlas';nav.innerHTML=icon('spark')+'<span>拾光百科</span>';
 document.querySelector('.sidebar nav').insertBefore(nav,document.querySelector('.sidebar nav .nav-separator'));
 const baseRender=render,baseNavigate=navigate;
 navigate=function(page){if(page==='atlas'){a.tab='today';a.selected=null;history.replaceState(null,'','#atlas?view=today')}else if(location.hash.startsWith('#atlas'))history.replaceState(null,'',location.pathname+location.search);baseNavigate(page)};
 render=function(){baseRender();document.body.classList.toggle('aw-studio',state.page==='atlas');document.querySelector('#content').classList.toggle('aw-workspace',state.page==='atlas');clearTimeout(a.timer);if(state.page==='atlas'){paint();if(local&&!a.loading)load()}else if(state.page==='dashboard'){
  const btn=document.querySelector('.hero [data-action="create"]');if(btn){delete btn.dataset.action;btn.dataset.nav='atlas';btn.innerHTML='开始今日创作 '+icon('arrow')}
  const p=document.querySelector('.hero-copy p');if(p)p.innerHTML='从选题到发布准备，<br>在拾光百科完成今天的创作。';
 }else if(state.page==='contents'){
  document.querySelector('#content').insertAdjacentHTML('afterbegin','<div class="notice-box">拾光百科的生成作品统一保存在作品库。 <button class="small-link" data-workspace="library">打开拾光百科作品库 →</button></div>');
 }};
 async function api(url,body){if(body!==undefined)a.version++;const options=body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-Orbit-Token':a.token},body:JSON.stringify(body)};const response=await fetch(url,options);const result=await response.json();if(!response.ok)throw new Error(result.error||'操作未完成');return result}
 async function queue(){adopt(await api('/api/queue'))}
 async function load(){if(a.loading)return;a.loading=true;const version=a.version;try{const b=await api('/api/bootstrap');if(version!==a.version)return;if(b.workspaceVersion!==2)throw new Error('本机服务版本较旧，请重新运行“启动工作台.cmd”，启动器会打开新版工作台。');a.limits=b.publishingLimits||a.limits;a.token=b.token;a.caps=b.capabilities;adopt(b.queueConfig||{items:b.queue});a.jobs=b.jobs;a.loaded=true;a.error='';document.querySelector('.live').innerHTML='<i></i>本机创作空间'}catch(e){a.error='连接本机服务失败，请运行“启动工作台.cmd”。'+e.message}finally{a.loading=false;if(state.page==='atlas'){paint();poll()}}}
 function poll(){clearTimeout(a.timer);if(state.page!=='atlas'||!local||!a.loaded)return;a.timer=setTimeout(async()=>{if(a.loading||a.busy){poll();return}try{const version=a.version;const jobs=a.jobs.filter(active);if(jobs.length)await Promise.all(jobs.map(j=>api('/api/jobs/'+j.id)));if(version!==a.version){poll();return}await load()}catch(e){a.error='进度连接暂时中断：'+e.message;paint();poll()}},running()?3000:15000)}
 function go(tab,id=null,restore=false){if(!a.selected)a.scroll[a.tab]=window.scrollY;const from=a.selected?a.origin:a.tab;a.tab=tab;a.origin=id?from:tab;a.selected=id;a.error='';a.publishResult=null;const hash=id?'#atlas?view='+tab+'&job='+encodeURIComponent(id)+'&from='+from:'#atlas?view='+tab;history.pushState(null,'',hash);state.page='atlas';baseRender();paint();poll();window.scrollTo(0,restore?(a.scroll[tab]||0):0);document.querySelector('.aw-title')?.focus({preventScroll:true})}
 function badge(j){return `<span class="aw-badge aw-${stage(j)}">${esc(labels[stage(j)])}</span>${j.mode==='test'?'<span class="aw-badge aw-test">测试</span>':''}`}
 function blank(title,body,action=''){return `<div class="aw-empty"><span>${icon('file')}</span><h3>${title}</h3><p>${body}</p>${action}</div>`}
 function top(){return `<div class="aw-heading"><div class="aw-brand-lockup"><span class="aw-studio-mark" aria-hidden="true">${icon('spark')}</span><div><div class="aw-brand-line"><h1 class="aw-title" tabindex="-1">拾光百科</h1><span>CREATIVE STUDIO</span></div><p>选题、图文与发布，你的专属创作空间。</p></div></div><details class="aw-environment"><summary><i class="connected-dot"></i>${a.loaded?(a.caps?.available?'创作环境就绪':'环境待检查'):'本机创作空间'}</summary><div><p>${esc(a.caps?.reason||'图文保存在本机，最终发布在小红书完成。')}</p><button class="btn" data-aw="refresh" ${a.busy?'disabled':''}>刷新状态</button></div></details></div><div class="aw-navigation"><nav class="aw-tabs" aria-label="拾光百科工作区">${[['today','今日创作','spark'],['library','作品库','image'],['topics','选题库','layers']].map(([key,label,symbol],i)=>`<button data-workspace="${key}" ${(!a.selected&&a.tab===key)||(a.selected&&key==='library')?'aria-current="page"':''}>${icon(symbol)}${label}${key==='library'&&a.loaded?`<span>${a.jobs.filter(j=>j.mode==='production').length}</span>`:''}<small>0${i+1}</small></button>`).join('')}</nav><span class="aw-nav-note">本机保存 <i>·</i> 拾光知识计划</span></div>`}
 function record(j){return `<article class="aw-record"><button class="aw-cover" data-job="${j.id}" aria-label="查看 ${esc(j.topic)}">${j.images[0]?`<img src="${esc(j.images[0].url)}" alt="${esc(j.topic)}封面" loading="lazy">`:icon('image')}</button><div class="aw-record-info"><button data-job="${j.id}" class="aw-record-title">${esc(j.caption?.title||j.topic)}</button><p>${esc(stamp(j.createdAt))} · ${styleLabel(jobStyle(j))} · ${j.images.length} 张图片</p><div class="aw-badges">${badge(j)}</div></div><button class="btn ${stage(j)==='publish'?'btn-primary':''}" data-job="${j.id}" ${stage(j)==='publish'?'data-prepare="true"':''}>${({generating:'查看进度',review:'查看并检查',publish:'去发布',published:'查看作品',failed:'查看并恢复',parked:'查看暂存作品'})[stage(j)]} ${icon('arrow')}</button></article>`}
 function styleCards(style,locked){return `<fieldset class="aw-style-options"><legend>图片风格 <small>历史样图参考</small></legend>${[['illustration','清晰插画','细腻线条 · 知识图解'],['photoreal','摄影写实','真实材质 · 自然光影']].map(([value,label,description])=>{const sample=a.jobs.find(j=>j.ready&&jobStyle(j)===value&&j.images.length);return `<label class="aw-style-card"><input type="radio" name="aw-visual-style" id="aw-style-${value}" value="${value}" ${style===value?'checked':''} ${locked?'disabled':''}><span class="aw-style-thumb">${sample?`<img src="${esc(sample.images[0].url)}" alt="${label}的历史样图" loading="lazy">`:`<span aria-hidden="true">${icon(value==='illustration'?'file':'image')}</span>`}</span><span class="aw-style-copy"><strong>${label}</strong><small>${description}</small></span><span class="aw-style-check" aria-hidden="true"></span></label>`}).join('')}</fieldset>`}
 function showcase(){const j=a.jobs.find(j=>j.ready&&j.images.length);if(!j)return `<section class="aw-showcase panel"><div class="aw-card-heading"><span><i>02</i> 作品预览</span><small>CREATION PREVIEW</small></div><div class="aw-preview-empty"><div class="aw-paper-outline"><span>拾光百科</span>${icon('image')}<small>你的第一篇作品</small></div><h3>把一个好问题，变成一组好图文。</h3><p>完成首次生成后，这里会展示你的真实作品。</p></div></section>`;
  return `<section class="aw-showcase panel"><div class="aw-card-heading"><span><i>02</i> 最近完成</span><div class="aw-badges">${badge(j)}</div></div><button class="aw-print-stage" data-job="${j.id}" aria-label="预览最近完成的作品：${esc(j.topic)}"><span class="aw-stage-grid" aria-hidden="true"></span><span class="aw-paper-stack">${j.images.slice(0,3).map((im,i)=>`<img class="aw-paper aw-paper-${i}" src="${esc(im.url)}" alt="${esc(j.topic)}${i?'内页 '+i:'封面'}" loading="lazy">`).join('')}</span><span class="aw-stage-caption">${String(j.images.length).padStart(2,'0')} PAGES <i>·</i> ${styleLabel(jobStyle(j))}</span><span class="aw-preview-link">查看完整作品 ${icon('arrow')}</span></button><div class="aw-showcase-caption"><div><span class="aw-subtle">${esc(stamp(j.createdAt))} · ${j.mode==='test'?'测试作品':'正式作品'}</span><h3><button data-job="${j.id}">${esc(j.caption?.title||j.topic)}</button></h3><p>${esc((j.caption?.body||'图文已完成，打开作品检查图片和文案。').replace(/\s+/g,' ').slice(0,110))}</p></div></div></section>`;
 }
 function workInbox(){const review=a.jobs.filter(j=>j.mode==='production'&&stage(j)==='review'),waiting=a.jobs.filter(j=>j.mode==='production'&&stage(j)==='publish'),items=[...waiting,...review];return `<section class="aw-inbox"><div class="aw-section-head"><div><span class="aw-kicker">KEEP IT MOVING</span><h2>接下来处理</h2></div><span class="aw-inbox-count">${items.length}</span></div><div class="panel aw-inbox-panel">${items.slice(0,3).map(j=>`<button class="aw-inbox-item" data-job="${j.id}"><span class="aw-inbox-icon">${icon(stage(j)==='publish'?'send':'file')}</span><span><small>${stage(j)==='publish'?'准备发布':'检查图片与文案'}</small><strong>${esc(j.caption?.title||j.topic)}</strong></span>${icon('arrow')}</button>`).join('')||`<div class="aw-inbox-clear">${icon('check')}<strong>暂时没有待处理的正式作品</strong><p>生成完成后，待检查和待发布的作品会出现在这里。</p></div>`}<div class="aw-inbox-foot"><span>检查内容</span><i>→</i><span>准备发布</span><i>→</i><span>记录结果</span></div></div><button class="aw-topics-shortcut" data-workspace="topics"><span>${icon('layers')} 选题储备 <b>${pending().length}</b></span><span>管理选题 ${icon('arrow')}</span></button></section>`}
 function pendingNotice(){const p=a.config?.pending;if(!p?.jobId)return '';return `<div class="notice-box aw-pending-notice" role="status"><strong>这篇还需要处理，但不必现在继续</strong><p>${esc(p.message?.slice(0,260)||'任务尚未完成验收，已有图片和文案均已保留。')}</p><p>可以直接创作其他选题；暂存会释放本篇选题，原作品仍可在作品库继续处理。</p><div class="aw-pending-actions"><button class="btn" data-job="${esc(p.jobId)}">查看原因与已有素材</button><button class="btn" data-aw="park" ${a.busy?'disabled':''}>暂存，开始新创作</button></div></div>`}
 function runningCards(){const jobs=a.jobs.filter(active);if(!jobs.length)return '';return `<section class="aw-parallel"><div class="aw-section-head"><h2>正在创作 <small>${jobs.length} / ${a.config?.concurrency?.max||1}</small></h2><span class="aw-subtle">每篇独立运行，可继续创建其他选题</span></div><div class="aw-parallel-grid">${jobs.map(j=>`<article class="panel aw-running" data-running-job="${j.id}"><div class="aw-progress-track"><i></i></div><h3>${esc(j.topic)}</h3><strong>${esc({queued:'准备中',generating:'生成图文中',reviewing:'复审与修正中',validating:'验收中'}[j.status])}</strong><p>${esc(j.message||'任务进行中')}</p><button class="btn" data-job="${j.id}">查看本篇进度 ${icon('arrow')}</button></article>`).join('')}</div></section>`}
 function today(){const jobs=a.jobs.filter(j=>day(j.createdAt)===day(Date.now())),formal=jobs.filter(j=>j.mode==='production'),waiting=a.jobs.filter(j=>j.mode==='production'&&stage(j)==='publish'),reviewing=a.jobs.filter(j=>j.mode==='production'&&stage(j)==='review'),runs=a.jobs.filter(active),next=a.productionTopic||a.config?.nextAvailable||(a.config?.available?null:pending()[0]),topic=a.mode==='test'?(a.testTopic||pending()[0]?.topic):next?.topic,style=a.visualStyle,limit=a.config?.concurrency?.max||1,full=runs.length>=limit,recents=a.recentFilter==='today'?jobs:a.jobs.slice(0,4);
  return `<div class="aw-today-intro"><div><span class="aw-kicker">${day(Date.now()).replaceAll('-',' / ')} · ${new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',weekday:'long'}).format(new Date())}</span><h2>今天，创作什么？</h2></div><div class="aw-summary"><span><small>今日正式生成</small><b>${String(formal.filter(j=>j.ready).length).padStart(2,'0')}</b><em>篇</em></span><button data-aw="pending-review" aria-label="待检查 ${reviewing.length}"><small>待检查</small><b>${String(reviewing.length).padStart(2,'0')}</b>${icon('arrow')}</button><button data-aw="pending-publish" aria-label="全部待发布 ${waiting.length} →"><small>待发布</small><b>${String(waiting.length).padStart(2,'0')}</b>${icon('arrow')}</button></div></div>
  ${runningCards()}${pendingNotice()}<div class="aw-studio-grid"><section class="panel aw-launch"><div class="aw-card-heading"><span><i>01</i> ${runs.length?'再创作一篇':'开始新创作'}</span><span class="aw-mode-tag">${a.mode==='test'?'独立测试':'正式图文'}</span></div><div class="aw-topic-title"><div><span class="aw-topic-category">${esc(a.queue.find(q=>q.topic===(topic))?.category||'知识百科')}</span><h2>${esc(topic||'还没有待创作选题')}</h2><p>${runs.length?'其他任务会继续运行，本篇可独立选择选题与风格。':'从选题库接续灵感，也可以换一个题目。'}</p></div><button class="aw-change-topic" data-aw="choose" ${a.busy?'disabled':''}>更换选题 ${icon('arrow')}</button></div>
  <div class="aw-output-plan"><span>${icon('image')} AI 规划 1–11 张图</span><i>·</i><span>${icon('layers')} 每张介绍一个对象</span><i>＋</i><span>${icon('file')} 专业解读文案</span></div>${styleCards(style,a.busy)}<label class="aw-content-review-toggle"><input id="aw-content-review" type="checkbox" ${a.reviewEnabled?'checked':''} ${a.busy?'disabled':''}><span><strong>Codex 内容复审</strong><small>生成后逐张核对事实与文案，发现问题自动修正。关闭则跳过额外复审。</small></span></label><div class="aw-settings-row"><span>${a.mode==='test'?'独立测试不会推进正式选题':'单图兼封面；多图为封面＋独立对象内页'}</span><details class="aw-advanced" ${a.advanced?'open':''}><summary>更多设置</summary><div class="aw-advanced-popover"><label>运行模式<select id="aw-mode" ${a.busy?'disabled':''}><option value="production" ${a.mode==='production'?'selected':''}>正式生成</option><option value="test" ${a.mode==='test'?'selected':''}>独立测试</option></select></label><p>独立测试不会推进正式选题，成果带有测试标识。</p><button class="small-link" data-aw="config">高级选题配置 →</button></div></details></div><button class="btn btn-primary aw-generate" data-aw="generate" ${a.busy||full||!a.caps?.available||a.config?.error||!topic?'disabled':''}><span>${icon('spark')}${a.busy?'正在提交…':full?'并行任务已满（'+limit+'篇）':a.mode==='test'?'生成测试图文':'生成本篇图文'}</span>${icon('arrow')}</button><div class="aw-launch-note"><span><i></i>生成后自动保存</span><span>检查完成后再发布</span></div></section>${showcase()}</div>
  <div class="aw-bottom-grid"><section class="aw-recent"><div class="aw-section-head"><div><span class="aw-kicker">YOUR COLLECTION</span><h2>作品动态</h2></div><div class="aw-recent-switch"><button data-recent-filter="recent" aria-pressed="${a.recentFilter==='recent'}">最近作品</button><button data-recent-filter="today" aria-pressed="${a.recentFilter==='today'}">今日作品 <span>${jobs.length}</span></button></div><button class="small-link" data-workspace="library">全部作品 ${icon('arrow')}</button></div><div class="aw-recent-grid">${recents.map(record).join('')||blank('今天的第一篇，从这里开始','选择上方的选题和图片风格，点击“生成本篇图文”。')}</div></section>${workInbox()}</div>`;
 }
 function filteredJobs(){const query=a.query.trim().toLowerCase();return a.jobs.filter(j=>(a.kind==='all'||j.mode===a.kind)&&(a.filter==='all'||stage(j)===a.filter)&&(!a.date||day(j.createdAt)===a.date)&&(!query||[j.topic,j.caption?.title].filter(Boolean).join(' ').toLowerCase().includes(query)))}
 function libraryResults(){const jobs=filteredJobs();return `<p class="aw-count">${jobs.length} 篇作品 · 按生成时间倒序</p><section class="panel aw-records">${jobs.slice(0,a.limit).map(record).join('')||blank(a.jobs.length?'没有符合条件的作品':'作品库还是空的',a.jobs.length?'试试其他标题、日期或筛选条件。':'完成首次生成后，文案与图片会保存在这里。',a.jobs.length?'<button class="btn" data-aw="clear-filters">清除筛选</button>':'<button class="btn btn-primary" data-workspace="today">去创作第一篇</button>')}</section>${jobs.length>a.limit?'<button class="btn aw-more" data-aw="more">加载更多作品</button>':''}`}
 function library(){return `<div class="aw-section-head"><div><h2>作品库</h2><p>每一次创作都在这里。检查内容、准备发布，或找回之前的作品。</p></div><button class="btn btn-primary" data-workspace="today">${icon('spark')}新建创作</button></div><div class="aw-filters"><label class="aw-search">${icon('search')}<input id="aw-query" type="search" placeholder="搜索作品标题或选题" value="${esc(a.query)}" aria-label="搜索作品"></label><label>生成日期<input id="aw-date" type="date" value="${esc(a.date)}"></label><label>作品类型<select id="aw-kind">${[['production','正式作品'],['test','测试作品'],['all','全部类型']].map(([v,t])=>`<option value="${v}" ${v===a.kind?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="aw-status-filters" aria-label="作品状态">${[['all','全部'],['generating','生成中'],['review','待检查'],['publish','待发布'],['published','已发布'],['failed','失败 / 中断'],['parked','已暂存']].map(([v,t])=>`<button data-status="${v}" aria-pressed="${a.filter===v}">${t}</button>`).join('')}</div><div id="aw-library-results" aria-live="polite">${libraryResults()}</div>`}
 function topicResults(){const rows=a.queue.filter(q=>(a.topicFilter==='all'||q.status===a.topicFilter)&&(!a.topicQuery||[q.topic,q.category].join(' ').toLowerCase().includes(a.topicQuery.toLowerCase()))),locked=a.config?.locked||a.busy;return `<p class="aw-count">${rows.length} 个选题 · ${pending().length} 个待创作</p><section class="panel aw-topic-list">${rows.map(q=>`<article class="aw-topic-row"><span class="aw-topic-number">${String(a.queue.indexOf(q)+1).padStart(2,'0')}</span><div class="aw-topic-info"><strong>${esc(q.topic)}</strong><p>${esc(q.category)} <span class="aw-badge ${q.status==='TODO'?'':'aw-published'}">${q.reserved?'已有任务':q.status==='TODO'?'待创作':'已生成'}</span>${q.line===(a.config?.available?a.config.nextAvailable?.line:pending()[0]?.line)?'<span class="aw-badge aw-review">下一篇</span>':''}</p></div><div class="aw-topic-actions">${q.status==='TODO'?`<button class="btn" data-topic-action="next" data-line="${q.line}" ${locked||q.line===(a.config?.available?a.config.nextAvailable?.line:pending()[0]?.line)?'disabled':''}>设为下一篇</button>`:`<button class="btn" data-topic-action="existing" data-line="${q.line}">查看已有作品</button><button class="btn" data-topic-action="regenerate" data-line="${q.line}" ${locked?'disabled':''}>再次生成</button>`}<button class="btn" data-topic-action="edit" data-line="${q.line}" ${locked?'disabled':''}>编辑</button><button class="aw-sort" data-topic-action="up" data-line="${q.line}" aria-label="上移 ${esc(q.topic)}" ${locked||a.queue.indexOf(q)===0?'disabled':''}>↑</button><button class="aw-sort" data-topic-action="down" data-line="${q.line}" aria-label="下移 ${esc(q.topic)}" ${locked||a.queue.indexOf(q)===a.queue.length-1?'disabled':''}>↓</button></div></article>`).join('')||blank('这里暂时没有选题','添加一个新选题，或切换筛选查看其他内容。')}</section>`}
 function topics(){return `<div class="aw-section-head"><div><h2>选题库</h2><p>决定下一篇写什么，也安排接下来的创作顺序。</p></div><button class="btn btn-primary" data-aw="add-topic" ${a.config?.locked||a.busy?'disabled':''}>＋ 添加选题</button></div>${a.config?.locked?`<div class="notice-box">${esc(a.config.lockReason)}。已有作品仍可查看。</div>${pendingNotice()}`:''}<div class="aw-filters"><label class="aw-search">${icon('search')}<input id="aw-topic-query" type="search" placeholder="搜索选题或分类" value="${esc(a.topicQuery)}" aria-label="搜索选题"></label><label>创作进度<select id="aw-topic-filter"><option value="TODO" ${a.topicFilter==='TODO'?'selected':''}>待创作</option><option value="已生成" ${a.topicFilter==='已生成'?'selected':''}>已生成</option><option value="all" ${a.topicFilter==='all'?'selected':''}>全部选题</option></select></label><button class="btn" data-aw="config">高级配置</button></div><div id="aw-topic-results">${topicResults()}</div>`}
 function publishGuide(j){const r=a.publishResult?.id===j.id?a.publishResult.value:null;return r?`<div class="atlas-publish-guide" role="status"><strong>发布准备已执行，请在小红书完成上传和发布</strong><p>${['browser','folder','caption','preview','clipboard'].map((k,i)=>`${r[k]?'✓':'未完成：'} ${['小红书页面','素材文件夹','文案窗口','封面预览','图片路径复制'][i]}`).join(' · ')}</p><ol><li>在小红书选择“上传图文”，在文件选择窗口按 Ctrl + V 粘贴图片路径。</li><li>复制本页的标题和正文，粘贴到小红书对应位置。</li><li>检查后在小红书完成最终发布，再回到这里标记已发布。</li></ol><a href="https://creator.xiaohongshu.com/publish/publish?source=official&target=image" target="_blank" rel="noopener">直接打开小红书创作中心 ↗</a></div>`:''}
 function detail(){const j=current();if(!j)return blank('没有找到这篇作品','记录可能已移走，请返回作品库查看。','<button class="btn" data-workspace="library">返回作品库</button>');const s=stage(j),retry=['failed','parked'].includes(s);return `<button class="aw-back" data-aw="back">← 返回${{today:'今日创作',library:'作品库',topics:'选题库'}[a.origin]}</button><div class="aw-detail-heading"><div><h2 class="aw-title" tabindex="-1">${esc(j.caption?.title||j.topic)}</h2><p>${esc(stamp(j.createdAt))} · ${j.mode==='test'?'独立测试':'正式作品'} · ${styleLabel(jobStyle(j))} · ${j.images.length} 张图片</p></div><div class="aw-badges">${badge(j)}</div></div>${j.mode==='test'?'<div class="aw-test-notice">这是测试作品，未推进正式选题队列。</div>':''}
  ${j.queueDetached?'<div class="aw-test-notice">这篇作品已独立暂存，素材完整保留。继续处理与发布不会自动修改当前选题进度。</div>':a.config?.pending?.jobId===j.id?pendingNotice():''}<div class="aw-workflow" aria-label="作品流程">${[['生成图文',true],['检查内容',j.ready],['准备发布',!!j.reviewedAt],['标记发布',!!j.publication]].map(([name,done],i)=>`<span class="${done?'is-done':''}"><i>${i+1}</i>${name}</span>`).join('')}</div>
  ${!j.ready?`<div class="${retry?'atlas-error':'aw-running'}" role="status"><strong>${esc({queued:'准备中',generating:'正在生成图文',reviewing:'Codex 正在复审与修正',validating:'逐页验收',failed:'生成遇到问题',interrupted:'生成已中断',cancelled:'生成已停止',parked:'作品已暂存'}[j.status]||'等待生成')}</strong><p>${esc(j.message||'请稍候')}</p>${active(j)?'<small>切换页面不会中断生成。</small>':'<small>已有素材已保留，继续生成会优先复用已完成的内容。</small>'}</div>`:''}
  ${j.queueUpdate&&j.queueUpdate.status!=='committed'?`<div class="notice-box"><p>${esc(j.queueUpdate.message||'选题进度尚未同步，图文素材已保留。')}</p><button class="btn" data-aw="sync-queue">重试同步选题</button></div>`:''}<div class="notice-box aw-review-result"><strong>${j.contentReview?.status==='passed'?(j.ready?'Codex 复审通过':j.status==='failed'?'内容复审完成，成品验收未通过':'内容复审完成，正在验收'):j.contentReview?.status==='running'?'Codex 复审中':j.contentReview?.status==='failed'?'Codex 复审未通过':j.contentReview?.status==='cancelled'?'Codex 复审已停止':j.contentReview?.status==='interrupted'?'Codex 复审已中断':j.reviewEnabled?'Codex 复审待完成':'未进行额外 Codex 复审'}</strong>${j.contentReview?.summary?`<p>${esc(j.contentReview.summary)} · 修订 ${j.contentReview.issueCount} 项</p>`:''}${j.ready&&j.contentReview?.status==='passed'?'<p class="aw-subtle">宿主最终验收已通过：文件、字数与生成证据已核对。</p>':''}${!active(j)&&j.images.length&&j.caption?'<button class="btn" data-aw="content-review">Codex 复审并修正</button>':''}</div>
  ${j.accessWarning?`<div class="atlas-error">${esc(j.accessWarning)}</div>`:''}${publishGuide(j)}
  ${j.publication?`<div class="aw-publication"><div><strong>已手动标记发布</strong><p>${esc(stamp(j.publication.markedAt))} · 由你确认，未通过平台自动核验。</p>${j.publication.url?`<a href="${esc(j.publication.url)}" target="_blank" rel="noopener">查看小红书作品 ↗</a>`:''}</div><button class="btn" data-aw="publication">编辑发布记录</button></div>`:''}
  <section class="panel atlas-job aw-job"><div class="atlas-delivery"><div><div class="atlas-section-label">图片预览 <span>封面在前 · 点击查看原图</span></div><div class="atlas-gallery">${j.images.length?j.images.map((im,i)=>`<button class="atlas-image" data-atlas-image="${esc(im.url)}" data-title="${esc(im.name)}"><img src="${esc(im.url)}" alt="${esc(im.name)}" loading="lazy"><span>${i===0?(j.expectedImages===1?'单图介绍 · 兼封面':'封面'):'内页 '+i}<small>${im.dimensions?im.dimensions.width+' × '+im.dimensions.height:'原始图片'}</small></span></button>`).join(''):Array.from({length:j.expectedImages||3},(_,i)=>`<div class="atlas-image skeleton"><div>${icon(i?'file':'image')}</div><span>${i?'内页生成后在此展示':'封面生成后在此展示'}</span></div>`).join('')}</div><div class="atlas-image-actions"><button class="btn" data-aw="paths" ${!j.ready||a.busy?'disabled':''}>${icon('link')}复制全部图片路径</button><span class="aw-subtle">按封面、内页顺序复制</span></div></div><div class="atlas-copy"><div class="atlas-section-label">小红书文案 <span>${j.caption?Array.from(j.caption.body.replace(/\r\n?/g,'\n').trim()).length+' / '+a.limits.maxBodyChars+' 字（含标签）':'等待生成'}</span></div><div class="atlas-copy-head"><h3>${esc(j.caption?.title||'标题生成后在此展示')}</h3><button data-aw="title" ${!j.ready||a.busy?'disabled':''}>复制标题</button></div><div class="atlas-copy-body">${esc(j.caption?.body||'正文与话题标签会随本篇作品一起保存。')}</div><button class="btn" data-aw="body" ${!j.ready||a.busy?'disabled':''}>${icon('file')}复制正文与标签</button></div></div><details class="atlas-log"><summary>生成记录与保存位置</summary><p class="atlas-path">${esc(j.project)}</p>${j.quantityPlan?`<p>${esc(j.quantityPlan.rationale)}</p>`:''}${j.events.slice(-12).reverse().map(e=>`<div><time>${esc(stamp(e.time))}</time><span>${esc(e.message)}</span></div>`).join('')}</details></section>
  <div class="aw-detail-bar"><div><strong>${esc(j.topic)}</strong><span>${s==='review'?'请检查图片、标题和正文，确认无误后准备发布。':s==='publish'?'最终上传与发布在小红书完成。':s==='published'?'发布记录保存在本机，可撤销误标记。':'已有成果保留在本机。'}</span></div><div class="aw-bar-actions"><button class="btn" data-aw="folder" ${a.busy?'disabled':''}>打开素材文件夹</button>${s==='review'?'<button class="btn btn-primary" data-aw="review">检查完成，准备发布</button>':s==='publish'?`<button class="btn" data-aw="publication">标记已发布</button><button class="btn btn-primary" data-aw="publish">${icon('send')}去小红书发布</button>`:s==='published'?'<button class="btn" data-aw="publish">再次准备发布</button>':retry?'<button class="btn btn-primary" data-aw="retry">继续生成</button>':['queued','generating','reviewing'].includes(j.status)?'<button class="btn" data-aw="cancel">停止生成</button>':'<span class="aw-subtle">正在验收，请稍候</span>'}</div></div>`}
 function paint(){if(state.page!=='atlas')return;document.body.classList.add('aw-studio');const focused=document.activeElement,focusId=focused?.closest('#content')?focused.id:null,selection=focusId&&['text','search'].includes(focused.type)?[focused.selectionStart,focused.selectionEnd]:null;const focusAttrs=focused?.closest('#content')?['data-aw','data-job','data-workspace','data-status','data-topic-action','data-line','data-recent-filter'].filter(key=>focused.hasAttribute(key)).map(key=>'['+key+'="'+CSS.escape(focused.getAttribute(key))+'"]'):[];const advanced=document.querySelector('.aw-advanced');if(advanced)a.advanced=advanced.open;const openLog=document.querySelector('.atlas-log')?.open,openEnv=document.querySelector('.aw-environment')?.open;const content=document.querySelector('#content');content.classList.add('aw-workspace');
  if(!local){content.innerHTML=top()+blank('打开本机创作空间','图文生成和发布准备需要在你的电脑上运行。','<a class="btn btn-primary" href="http://127.0.0.1:4173/#atlas?view=today">打开本机工作台</a>');return}
  if(!a.loaded){content.innerHTML=top()+`<div class="notice-box" role="status">${esc(a.error||'正在读取作品和选题…')}</div><button class="btn" data-aw="refresh">重新连接</button>`;return}
  content.innerHTML=top()+`${a.error?`<div class="atlas-error" role="alert">${esc(a.error)}</div>`:''}${a.config?.error?`<div class="atlas-error">选题配置需要修复：${esc(a.config.error)} <button class="btn" data-aw="config">打开高级配置</button></div>`:''}${a.selected?detail():({today,library,topics})[a.tab]()}<footer class="footer"><span><i class="connected-dot"></i>本机保存 · Asia/Shanghai</span><span>拾光百科 / 创作工作台</span></footer>`;
  if(a.busy)content.querySelectorAll('[data-aw],[data-topic-action]').forEach(el=>el.disabled=true);
  if(openLog&&document.querySelector('.atlas-log'))document.querySelector('.atlas-log').open=true;if(openEnv)document.querySelector('.aw-environment').open=true;
  if(focusId){const input=document.getElementById(focusId);input?.focus({preventScroll:true});if(input&&selection)input.setSelectionRange(...selection)}else if(focusAttrs.length)document.querySelector(focusAttrs.join(''))?.focus({preventScroll:true});
 }
 function dialog(title,html){const d=document.createElement('dialog');d.className='aw-dialog';d.setAttribute('aria-label',title);d.innerHTML=`<div class="dialog-header"><h2>${title}</h2><button type="button" data-close aria-label="关闭弹窗">${icon('close')}</button></div>${html}`;document.body.append(d);d.querySelector('[data-close]').onclick=()=>d.close();d.addEventListener('close',()=>d.remove());d.showModal();return d}
 async function saveTopic(action,revision=a.config.revision){const q=await api('/api/queue',{revision,action});adopt(q);paint();return q}
 function topicForm(item){const revision=a.config.revision,d=dialog(item?'编辑选题':'添加选题',`<form><label class="field">选题标题<input name="topic" required maxlength="200" value="${esc(item?.topic||'')}" placeholder="例如：世界街头美食图鉴"></label><label class="field">分类<input name="category" required maxlength="200" value="${esc(item?.category||'')}" placeholder="例如：食物饮食"></label><p class="aw-subtle">保存后立即更新选题库，不影响已生成的作品。</p><p data-error role="alert"></p><div class="dialog-actions"><button class="btn btn-primary" type="submit">保存选题</button></div></form>`);const form=d.querySelector('form');form.onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{await saveTopic({type:item?'edit':'add',line:item?.line,topic:form.elements.topic.value,category:form.elements.category.value},revision);d.close();toast('选题已保存')}catch(err){d.querySelector('[data-error]').textContent=err.message}finally{button.disabled=false}}}
 function chooseTopic(){const rows=[...a.queue],d=dialog('更换本次选题',`<p class="aw-subtle">${a.mode==='test'?'仅选择本次测试的选题，正式顺序不变。':'选择本次创作选题，不改变其他任务或选题顺序。'}</p><input class="aw-choose-search" type="search" aria-label="搜索可选选题" placeholder="搜索选题或分类"><p data-error role="alert"></p><div class="aw-choices"></div>`);const list=d.querySelector('.aw-choices');function draw(query=''){const choices=rows.filter(q=>q.status==='TODO'&&(a.mode==='test'||(!q.reservedJobId&&!q.reserved))&&[q.topic,q.category].join(' ').includes(query));list.innerHTML=choices.map(q=>`<button data-choice="${q.line}"><strong>${esc(q.topic)}</strong><span>${esc(q.category)} →</span></button>`).join('')||'<p class="aw-subtle">没有待创作选题，请到选题库添加或查看已生成的选题。</p>'}draw();d.querySelector('input').oninput=e=>draw(e.target.value.trim());list.onclick=async e=>{const button=e.target.closest('[data-choice]');if(!button)return;const item=rows.find(q=>q.line===Number(button.dataset.choice));list.querySelectorAll('button').forEach(b=>b.disabled=true);try{if(a.mode==='test'){a.testTopic=item.topic;paint()}else{a.productionTopic={topic:item.topic,category:item.category};paint()}d.close();toast('本次选题已更新')}catch(err){d.querySelector('[data-error]').textContent=err.message;list.querySelectorAll('button').forEach(b=>b.disabled=false)}}}
 function regeneration(item){const revision=a.config.revision,existing=a.jobs.filter(j=>j.topic===item.topic),d=dialog('再次创作这个选题',`<h3>${esc(item.topic)}</h3><p>此选题已生成过${existing.length?'，作品库中有 '+existing.length+' 篇相关作品':''}。再次生成会保留原作品。</p><p class="aw-subtle">先将它设为下一篇，再选择图片风格并开始生成。</p><p data-error role="alert"></p><div class="dialog-actions"><button class="btn" data-existing>查看已有作品</button><button class="btn btn-primary" data-regenerate>设为下一篇，再次创作</button></div>`);d.querySelector('[data-existing]').onclick=()=>{d.close();a.query=item.topic;a.kind='all';a.filter='all';a.date='';go('library')};d.querySelector('[data-regenerate]').onclick=async e=>{e.target.disabled=true;try{await saveTopic({type:'next',line:item.line,regenerate:true},revision);d.close();a.mode='production';go('today')}catch(err){d.querySelector('[data-error]').textContent=err.message;e.target.disabled=false}}}
 function publicationForm(j){const d=dialog(j.publication?'发布记录':'标记已发布',`<h3>${esc(j.topic)}</h3><p>仅在你已经完成小红书发布后标记。此记录由你确认，不代表平台自动核验。</p><form><label class="field">作品链接（可选）<input name="url" type="url" maxlength="2048" value="${esc(j.publication?.url||'')}" placeholder="https://www.xiaohongshu.com/…"></label><p data-error role="alert"></p><div class="dialog-actions">${j.publication?'<button type="button" class="btn" data-unmark>撤销发布标记</button>':''}<button type="submit" class="btn btn-primary">${j.publication?'保存发布记录':'确认已在小红书发布'}</button></div></form>`);async function submit(published){d.querySelectorAll('button').forEach(b=>b.disabled=true);try{put(await api('/api/jobs/'+j.id+'/publication',{published,url:d.querySelector('input').value}));d.close();paint();toast(published?'已保存手动发布记录':'已撤销发布标记，作品回到待发布')}catch(e){d.querySelector('[data-error]').textContent=e.message}finally{d.querySelectorAll('button').forEach(b=>b.disabled=false)}}d.querySelector('form').onsubmit=e=>{e.preventDefault();submit(true)};if(j.publication)d.querySelector('[data-unmark]').onclick=()=>submit(false)}
 async function action(name){if(a.busy)return;const j=current();if(name==='refresh'){await load();return}if(name==='back'){go(a.origin,null,true);return}if(name==='config'){await window.openAtlasQueue({api,onSaved:async q=>{adopt(q);paint()}});return}if(name==='choose'){chooseTopic();return}if(name==='add-topic'){topicForm();return}if(name==='publication'){publicationForm(j);return}if(name==='more'){a.limit+=12;paint();return}if(name==='clear-filters'){a.query='';a.date='';a.filter='all';a.kind='all';paint();return}if(name==='pending-publish'||name==='pending-review'){a.query='';a.date='';a.kind='production';a.filter=name==='pending-publish'?'publish':'review';go('library');return}
  if(name==='park'||name==='park-choose'){const id=a.config?.pending?.jobId;if(!id)return;let parked=false;a.busy=true;a.error='';paint();try{put(await api('/api/jobs/'+id+'/park',{}));await queue();parked=true;if(a.selected)go('today');toast('已暂存到作品库，可以更换选题和图片风格')}catch(e){a.error=e.message}finally{a.busy=false;paint();poll()}if(parked&&name==='park-choose')chooseTopic();return}
  a.busy=true;a.error='';paint();try{switch(name){case 'generate':{const job=await api('/api/jobs',{mode:a.mode,visualStyle:a.visualStyle,reviewEnabled:a.reviewEnabled,queueRevision:a.config.revision,...(a.mode==='test'?(a.testTopic?{testTopic:a.testTopic}:{}):{topic:(a.productionTopic||a.config.nextAvailable)?.topic,topicCategory:(a.productionTopic||a.config.nextAvailable)?.category})});put(job);a.productionTopic=null;await queue();toast('已开始创作，可以查看当前进度');break}case 'sync-queue':put(await api('/api/jobs/'+j.id+'/sync-queue',{}));await queue();break;case 'content-review':put(await api('/api/jobs/'+j.id+'/content-review',{}));toast('已开始独立复审，原图文已备份');break;case 'review':put(await api('/api/jobs/'+j.id+'/review',{}));toast('检查完成，可以准备发布');break;case 'retry':put(await api('/api/jobs/'+j.id+'/retry',{}));await queue();break;case 'cancel':put(await api('/api/jobs/'+j.id+'/cancel',{}));await queue();break;case 'folder':await api('/api/jobs/'+j.id+'/open-folder',{});toast('已打开素材文件夹');break;case 'publish':{const result=await api('/api/jobs/'+j.id+'/publish',{});a.publishResult={id:j.id,value:result};put(await api('/api/jobs/'+j.id));toast('已执行发布准备，请在小红书完成发布');break}case 'title':case 'body':case 'paths':await api('/api/jobs/'+j.id+'/copy',{kind:name});toast({title:'标题已复制',body:'正文与标签已复制',paths:'图片路径已按发布顺序复制'}[name]);break}}catch(e){a.error=e.message;if(j)try{put(await api('/api/jobs/'+j.id))}catch{}}finally{a.busy=false;paint();poll();if(name==='publish'&&a.publishResult?.id===j?.id)document.querySelector('.atlas-publish-guide')?.scrollIntoView({block:'start',behavior:'smooth'})}}
 document.addEventListener('input',e=>{if(e.target.id==='aw-query'){a.query=e.target.value;a.limit=12;document.querySelector('#aw-library-results').innerHTML=libraryResults()}if(e.target.id==='aw-topic-query'){a.topicQuery=e.target.value;document.querySelector('#aw-topic-results').innerHTML=topicResults()}});
 document.addEventListener('change',e=>{if(e.target.id==='aw-content-review'){a.reviewEnabled=e.target.checked;try{localStorage.setItem('orbit.atlas.reviewEnabled',String(a.reviewEnabled))}catch{}paint();return}if(e.target.name==='aw-visual-style'){a.visualStyle=e.target.value;try{localStorage.setItem('orbit.atlas.visualStyle',a.visualStyle)}catch{}paint();return}switch(e.target.id){case 'aw-style':a.visualStyle=e.target.value;try{localStorage.setItem('orbit.atlas.visualStyle',a.visualStyle)}catch{}break;case 'aw-mode':a.mode=e.target.value;a.testTopic=null;break;case 'aw-kind':a.kind=e.target.value;a.limit=12;break;case 'aw-date':a.date=e.target.value;a.limit=12;break;case 'aw-topic-filter':a.topicFilter=e.target.value;break;default:return}paint()});
 document.addEventListener('toggle',e=>{if(e.target.matches('.aw-advanced'))a.advanced=e.target.open},true);
 document.addEventListener('click',async e=>{const button=e.target.closest('[data-workspace],[data-job],[data-status],[data-aw],[data-topic-action],[data-recent-filter]');if(!button||button.disabled)return;e.preventDefault();if(a.busy)return;if(button.dataset.recentFilter){a.recentFilter=button.dataset.recentFilter;paint();return}if(button.dataset.workspace){go(button.dataset.workspace);if(!a.loaded)load();return}if(button.dataset.job){go(a.tab,button.dataset.job);if(button.dataset.prepare&&stage(current())==='publish')await action('publish');return}if(button.dataset.status){a.filter=button.dataset.status;a.limit=12;paint();return}if(button.dataset.aw){await action(button.dataset.aw);return}const item=a.queue.find(q=>q.line===Number(button.dataset.line)),type=button.dataset.topicAction;if(!item)return;if(type==='edit'){topicForm(item);return}if(type==='regenerate'){regeneration(item);return}if(type==='existing'){a.query=item.topic;a.kind='all';a.filter='all';a.date='';go('library');return}a.busy=true;paint();try{await saveTopic({type:type==='next'?'next':'move',line:item.line,direction:type});toast(type==='next'?'已设为下一篇':'选题顺序已更新')}catch(err){a.error=err.message}finally{a.busy=false;paint()}});
 document.addEventListener('click',e=>{const b=e.target.closest('[data-atlas-image]');if(!b)return;const d=dialog(esc(b.dataset.title),`<div class="atlas-preview-tools"><span data-size>读取原图尺寸…</span><button class="btn" data-zoom>100% 原图</button><a class="btn" href="${esc(b.dataset.atlasImage)}" download="${esc(b.dataset.title)}">保存原图</a></div><div class="atlas-preview-scroll"><img src="${esc(b.dataset.atlasImage)}" alt="${esc(b.dataset.title)}"></div>`);d.classList.add('atlas-preview');const im=d.querySelector('img');im.onload=()=>d.querySelector('[data-size]').textContent=im.naturalWidth+' × '+im.naturalHeight+' · 原始 PNG';d.querySelector('[data-zoom]').onclick=e=>{e.target.textContent=d.classList.toggle('is-native')?'适应窗口':'100% 原图'}});
 window.addEventListener('hashchange',()=>{if(!location.hash.startsWith('#atlas'))return;route();state.page='atlas';render()});
 window.addEventListener('focus',()=>{if(local&&a.loaded&&state.page==='atlas'&&!a.busy&&!document.querySelector('dialog[open]'))load()});
 if(location.hash.startsWith('#atlas'))state.page='atlas';render();
})();
